using System.Text.Json;
using EqlTracker.Core;

internal static class ItemInspectionTests
{
    internal static void Register(Action<string, Action> test)
    {
        void Check(bool value) { if (!value) throw new Exception("Item inspection assertion failed"); }
        PetContextCatalog Context() => PetContextCatalog.Load(Path.Combine(AppContext.BaseDirectory, "data/pet-context.json"));
        PetBuild Earth(int rank = 10) => new() { PetType = "Earth", SummonSpell = "Greater Conjuration: Earth", SummonClass = "MAG", SummonRank = rank };
        test("Pet source cache provides canonical spell identities and base levels", () => { var c = Context(); Check(c.Spells.Count == 86 && c.Spells.All(s => s.BasePetLevel > 0 && s.LevelEvidence.Contains("revision") && s.Id.Length > 0)); Check(c.Spells.Select(s => s.Id).Distinct().Count() == 86); });
        test("Legacy NPC summon names resolve without displaying Summon suffix", () => { var c = Context(); var s = c.Find("Earth", "Greater Conjuration: Earth Summon", "MAG"); Check(s?.Name == "Greater Conjuration: Earth" && s.RequiredLevel == 46 && s.BasePetLevel == 41); });
        test("Greater Conjuration rank ten caps to level fifty owner", () => Check(Context().Estimate(Earth(), 50).Level == 50));
        test("Automatic level uses base pet level rather than caster requirement", () => Check(Context().Estimate(Earth(0), 50).Level == 41));
        test("Automatic pet rank increments until owner cap", () => { var c = Context(); Check(c.Estimate(Earth(3), 50).Level == 44 && c.Estimate(Earth(9), 50).Level == 50); });
        test("Unknown character level does not assume level fifty", () => Check(Context().Estimate(Earth(), 0).Level == null));
        test("Custom unknown spell does not invent base level", () => { var b = Earth(); b.SummonSpell = "Custom summon"; Check(Context().Estimate(b, 50).Level == null); });
        test("Unverified focus bonus is excluded and identified", () => { var b = Earth(0); b.Focus = "Staff of Elemental Mastery: Earth"; var e = Context().Estimate(b, 50); Check(e.Level == 41 && e.Explanation.Contains("excludes")); });
        test("Auto and manual pet level provenance survive restart", () => { var b = Earth(); b.LevelMode = PetLevelMode.Automatic; b.LevelEvidence = "Base 41"; b.PetLevel = 50; var copy = JsonSerializer.Deserialize<PetBuild>(JsonSerializer.Serialize(b))!; Check(copy.LevelMode == PetLevelMode.Automatic && copy.LevelEvidence == "Base 41" && copy.PetLevel == 50); });
        test("Level provenance is covered by context Undo", () => { var b = Earth(); b.PetLevel = 48; b.LevelMode = PetLevelMode.Manual; Check(PetBuildEditing.ApplyContext(b, "Earth", 50, b.SummonSpell, 10, "", false, out _, "MAG", PetLevelMode.Automatic, "Auto estimate")); Check(PetBuildEditing.Undo(b, out _) && b.PetLevel == 48 && b.LevelMode == PetLevelMode.Manual); });
        test("Legacy recorded levels remain unspecified for manual preservation", () => { var b = JsonSerializer.Deserialize<PetBuild>("{\"PetLevel\":47}")!; Check(b.LevelMode == PetLevelMode.Unspecified && b.PetLevel == 47); });
        test("Invalid context retains value and level provenance atomically", () => { var b = Earth(); b.PetLevel = 50; b.LevelMode = PetLevelMode.Automatic; string before = JsonSerializer.Serialize(b); Check(!PetBuildEditing.ApplyContext(b, "Earth", -1, b.SummonSpell, 10, "", true, out _, "MAG", PetLevelMode.Manual) && before == JsonSerializer.Serialize(b)); });
        test("All items collapses physical copies to highest recorded rank", () => { var items = new[] { new InventoryEntry { Name = "Blade +2", Location = "Bank2", Count = 1 }, new InventoryEntry { Name = "Blade +8", Location = "Bag1", Count = 1 } }; Check(PhysicalItemChoices.Rows(items, false).Single()!.Rank == 8 && PhysicalItemChoices.Rows(items, true).Count() == 2); });
        test("Physical choice ties use stable location without combining effects", () => { var a = new InventoryEntry { Name = "Blade +8", Location = "B", Augments = [new() { EffectText = "Effect A" }] }; var b = new InventoryEntry { Name = "Blade +8", Location = "A", Augments = [new() { EffectText = "Effect B" }] }; var result = PhysicalItemChoices.Rows(new[] { a, b }, false).Single()!; Check(ReferenceEquals(result, b) && result.Augments.Single().EffectText == "Effect B" && a.Augments.Single().EffectText == "Effect A"); });
        test("Unowned item remains one bare catalog row", () => Check(PhysicalItemChoices.Rows([], false).Single() == null));
        test("Range nonweapon is held item without invented focus effect", () => { var i = WikiClient.ParseItem("Ball", "{{Itempage\n|itemname = Ball\n|statsblock = Slot: RANGE<br>HP: +15<br>Class: ALL<br>Race: ALL<br>\n}}", 10); Check(PetItemRules.Type(i) == "Held item" && !i.Stats.ContainsKey("Ratio") && i.Effects.Count == 0); });
        test("Documented focus effect remains separate from held item classification", () => { var i = WikiClient.ParseItem("Focus", "{{Itempage\n|itemname = Focus\n|statsblock = Slot: RANGE<br>Class: ALL<br>Race: ALL<br>\n|focus_effect = Verified focus\n}}", 11); Check(i.Effects.Any(e => e.Contains("Verified focus")) && PetItemRules.Type(i) == "Held item"); });
        test("Shoulder singular and throwing aliases get readable types", () => { Check(PetItemRules.Type(new() { Slots = ["SHOULDER"] }) == "Shoulder armor"); Check(PetItemRules.CanonicalType("Throwingv2") == "Throwing" && PetItemRules.CanonicalType("1H Slashing /") == "1H Slashing"); });
        test("Quest category classification requires documented evidence", () => { var i = WikiClient.ParseItem("Ingredient", "{{Itempage\n|itemname = Ingredient\n|statsblock = MAGIC ITEM\n}}\n[[Category:Quest Items]]", 12); Check(i.Display.Type == "Quest item" && i.Display.TypeEvidence.Contains("category")); Check(PetItemRules.Type(new() { Name = "Quest item maybe" }) == "Unknown"); });
        test("Metadata priorities retain independent durable parser checkpoints", () => { string path = Path.Combine(Path.GetTempPath(), Guid.NewGuid()+".db"); try { using (var cache = new EquipmentCatalog(path)) { cache.Index(["A", "Z"]); Check(cache.Pending(DateTime.MinValue, 1, ["Z"]).Single() == "Z"); cache.Store([], ["Z"]); Check(cache.Pending(DateTime.MinValue, 2, ["Z"]).SequenceEqual(["A"])); } using var reopened = new EquipmentCatalog(path); Check(reopened.Pending(DateTime.MinValue).SequenceEqual(["A"])); } finally { File.Delete(path); } });
        test("Preview state is transient and independent of physical rank", () => { var entry = new InventoryEntry { Name = "Blade +13" }; var preview = new SelectedItemPreviewState("blade", 10, 1); Check(entry.Rank == 13 && preview.Rank == 10); preview = preview with { Rank = null, Revision = 2 }; Check(preview.Rank == null && entry.Rank == 13); });
    }
}
